type Snowflake struct {
    mu       sync.Mutex
    epoch    int64
    machine  int64
    seq      int64
    lastTime int64
}

func (s *Snowflake) NextID() int64 {
    s.mu.Lock()
    defer s.mu.Unlock()
    now := time.Now().UnixMilli()
    if now == s.lastTime {
        s.seq = (s.seq + 1) & 0xFFF
        if s.seq == 0 {                 // 序列号用完,等下一毫秒
            for now <= s.lastTime {
                now = time.Now().UnixMilli()
            }
        }
    } else {
        s.seq = 0
    }
    s.lastTime = now
    return ((now - s.epoch) << 22) | (s.machine << 12) | s.seq
}

