// 核心是位运算拼装。C++ 里常用于对 ID 生成性能敏感的场景
class Snowflake {
    static constexpr int64_t EPOCH = 1700000000000LL;
    std::mutex mu_;
    int64_t machine_, seq_ = 0, last_ = -1;
    int64_t now_ms() {
        return std::chrono::duration_cast<std::chrono::milliseconds>(
            std::chrono::system_clock::now().time_since_epoch()).count();
    }
public:
    explicit Snowflake(int64_t m) : machine_(m & 0x3FF) {}
    int64_t next() {
        std::lock_guard<std::mutex> lk(mu_);
        int64_t now = now_ms();
        if (now == last_) {
            seq_ = (seq_ + 1) & 0xFFF;
            if (seq_ == 0) while ((now = now_ms()) <= last_) {}
        } else seq_ = 0;
        last_ = now;
        return ((now - EPOCH) << 22) | (machine_ << 12) | seq_;
    }
};
